25	#if defined(__AVX2__)
26	
27	#define MM256_LOAD(row, x) \
28	    pix0##row = _mm256_cvtepi32_ps(mm256_cvtepu8_epi32(&in1[x])); \
29	    pix1##row = _mm256_cvtepi32_ps(mm256_cvtepu8_epi32(&in0[x])); \
