56	        __m256 kernel20 = _mm256_insertf128_ps(
57	            _mm256_set1_ps(kernel[6+0]),
58	            _mm_set1_ps(kernel[6+1]), 1);
59	        __m256 kernel21 = _mm256_castps128_ps256(_mm_set1_ps(kernel[6+2]));
60	        __m256 pix00, pix10, pix20;
61	        __m256 pix01, pix11, pix21;
62	        __m256 pix02, pix12, pix22;
