67	        for (; x < im->xsize-1-7; x += 8) {
68	            __m256 ss;
69	            __m128i ssi0, ssi1, ssi2, ssi3;
70	
71	            ss = _mm256_castps128_ps256(_mm_set1_ps(offset));
72	            MM256_SUM(0, 0);
73	            MM256_LOAD(1, x+1);
74	            MM256_SUM(1, 1);
75	            ssi0 = MM256_OUT(x);
76	
77	            ss = _mm256_castps128_ps256(_mm_set1_ps(offset));
78	            MM256_SUM(1, 0);
79	            MM256_LOAD(2, x+3);
