91	            MM256_SUM(1, 0);
92	            MM256_PERMUTE(0, 2, 2, 0x21);
93	            MM256_SUM(0, 1);
94	            ssi3 = MM256_OUT(x+3);
95	
96	            ssi0 = _mm_packs_epi32(ssi0, ssi1);
97	            ssi2 = _mm_packs_epi32(ssi2, ssi3);
98	            ssi0 = _mm_packus_epi16(ssi0, ssi2);
