100	            
101	            ss = _mm256_castps128_ps256(_mm_set1_ps(offset));
102	            MM256_SUM(2, 0);
103	            MM256_LOAD(1, x+5);
104	            MM256_SUM(1, 1);
105	            ssi0 = MM256_OUT(x+4);
106	            
107	            ss = _mm256_castps128_ps256(_mm_set1_ps(offset));
108	            MM256_SUM(1, 0);
109	            MM256_LOAD(0, x+7);
110	            MM256_SUM(0, 1);
111	            ssi2 = MM256_OUT(x+6);
112	            
113	            ss = _mm256_castps128_ps256(_mm_set1_ps(offset));
114	            MM256_PERMUTE(2, 2, 1, 0x21);
115	            MM256_SUM(2, 0);
116	            MM256_PERMUTE(1, 1, 0, 0x21);
117	            MM256_SUM(1, 1);
