126	            ssi0 = _mm_packs_epi32(ssi0, ssi1);
127	            ssi2 = _mm_packs_epi32(ssi2, ssi3);
128	            ssi0 = _mm_packus_epi16(ssi0, ssi2);
129	            _mm_storeu_si128((__m128i*) &out[x+4], ssi0);
130	        }
131	
132	        for (; x < im->xsize-1-1; x += 2) {
133	            __m256 ss;
134	            __m128i ssi0, ssi1;
135	
136	            ss = _mm256_castps128_ps256(_mm_set1_ps(offset));
137	            MM256_SUM(0, 0);
138	            MM256_LOAD(1, x+1);
139	            MM256_SUM(1, 1);
