144	            MM256_SUM(0, 0);
145	            MM256_PERMUTE(1, 0, 1, 0xf3);
146	            MM256_SUM(1, 1);
147	            ssi1 = MM256_OUT(x+1);
148	
149	            ssi0 = _mm_packs_epi32(ssi0, ssi1);
