                _mm_storeu_si128((__m128i *)shift1D_arr, _mm256_extractf128_si256(shift1D_0, 1));
                _mm_storeu_si128((__m128i *)shift2D_arr, _mm256_extractf128_si256(shift2D_0, 1));

                _mm_storeu_si128((__m128i *)idx1D_fixed_arr, _mm256_extractf128_si256(idx1D_fixed_0, 1));
                _mm_storeu_si128((__m128i *)idx2D_fixed_arr, _mm256_extractf128_si256(idx2D_fixed_0, 1));

