/*
 * SSE2-optimized version of ImagingColorLUT3D_linear
 * Processes 4 pixels at a time using 128-bit SIMD operations
 */
#if defined(__SSE4_2__)
Imaging
ImagingColorLUT3D_linear_SIMD(
    Imaging imOut,
    Imaging imIn,
    int table_channels,
    int size1D,
    int size2D,
    int size3D,
    INT16 *table) {

    UINT32 scale1D = (size1D - 1) / 255.0f * (1 << SCALE_BITS);
    UINT32 scale2D = (size2D - 1) / 255.0f * (1 << SCALE_BITS);
    UINT32 scale3D = (size3D - 1) / 255.0f * (1 << SCALE_BITS);
    int size1D_2D = size1D * size2D;
    int y;
    ImagingSectionCookie cookie;

    /* Precompute constant values */
    const __m128i zero = _mm_setzero_si128();
    const __m128i scale1D_m128 = _mm_set1_epi32(scale1D);
    const __m128i scale2D_m128 = _mm_set1_epi32(scale2D);
    const __m128i scale3D_m128 = _mm_set1_epi32(scale3D);
    const __m128i scaleMask_m128 = _mm_set1_epi32(SCALE_MASK);
    const __m128i shiftShift_m128 = _mm_set1_epi32(SHIFT_BITS);
    const __m128i scaleShift_m128 = _mm_set1_epi32(SCALE_BITS);

    /* Alignment for SIMD processing */
    int xsize_simd = (imOut->xsize / 4) * 4;

    ImagingSectionEnter(&cookie);

    if (table_channels == 3) {
        for (y = 0; y < imOut->ysize; y++) {
            UINT8 *rowIn = (UINT8 *)imIn->image[y];
            UINT8 *rowOut = (UINT8 *)imOut->image[y];

            for (int x = 0; x < xsize_simd; x += 4) {
                /* Load 4 pixels (16 bytes: 4 * 4 channels) */
                __m128i pixels = _mm_loadu_si128((__m128i *)(rowIn + x * 4));

                /* Extract R, G, B channels using SSSE3 pshufb */
                /* pixels format: R0,G0,B0,A0,R1,G1,B1,A1,... */

                /* Create masks for extracting R, G, B */
                /* R channel: bytes 0, 4, 8, 12 */
                /* G channel: bytes 1, 5, 9, 13 */
                /* B channel: bytes 2, 6, 10, 14 */

                /* Use unpacking to get R channel (bytes 0,4,8,12) */
                __m128i r_unpacked_lo = _mm_unpacklo_epi8(pixels, zero);  /* R0,R1 in low, R2,R3 in high */
                __m128i r_unpacked_hi = _mm_unpackhi_epi8(pixels, zero);  /* R4,R5 in low, R6,R7 in high */

                /* Actually, we need to interleave R properly */
                __m128i r01 = _mm_unpacklo_epi8(pixels, zero);  /* R0,R1 */
                __m128i r23 = _mm_unpackhi_epi8(pixels, zero);  /* R2,R3 */
                __m128i r02 = _mm_unpacklo_epi8(r01, r23);       /* R0,R2 */
                __m128i r13 = _mm_unpackhi_epi8(r01, r23);       /* R1,R3 */

                /* For G channel: bytes 1, 5, 9, 13 - use pshufb or shift+mask */
                __m128i pixels_shift1 = _mm_srli_si128(pixels, 1);
                __m128i g01 = _mm_unpacklo_epi8(pixels_shift1, zero);
                __m128i g23 = _mm_unpackhi_epi8(pixels_shift1, zero);
                __m128i g02 = _mm_unpacklo_epi8(g01, g23);
                __m128i g13 = _mm_unpackhi_epi8(g01, g23);

                /* For B channel: bytes 2, 6, 10, 14 */
                __m128i pixels_shift2 = _mm_srli_si128(pixels, 2);
                __m128i b01 = _mm_unpacklo_epi8(pixels_shift2, zero);
                __m128i b23 = _mm_unpackhi_epi8(pixels_shift2, zero);
                __m128i b02 = _mm_unpacklo_epi8(b01, b23);
                __m128i b13 = _mm_unpackhi_epi8(b01, b23);

                /* Compute scaled indices for R channel (r02 contains R0,R2 in each dword) */
                /* But we need R0,R1,R2,R3 in order - let me restructure */

                /* Actually let's just compute things scalar for each pixel */
                /* and use SIMD only for the table lookup phase */

                INT16 shift1D_arr[4], shift2D_arr[4], shift3D_arr[4];
                INT32 idx1D_fixed_arr[4], idx2D_fixed_arr[4], idx3D_fixed_arr[4];

                /* Load R values from r02 and r13 */
                INT32 r_vals[4];
                INT32 g_vals[4];
                INT32 b_vals[4];

                r_vals[0] = (INT32)(UINT8)rowIn[x * 4 + 0];
                r_vals[1] = (INT32)(UINT8)rowIn[x * 4 + 4];
                r_vals[2] = (INT32)(UINT8)rowIn[x * 4 + 8];
                r_vals[3] = (INT32)(UINT8)rowIn[x * 4 + 12];

                g_vals[0] = (INT32)(UINT8)rowIn[x * 4 + 1];
                g_vals[1] = (INT32)(UINT8)rowIn[x * 4 + 5];
                g_vals[2] = (INT32)(UINT8)rowIn[x * 4 + 9];
                g_vals[3] = (INT32)(UINT8)rowIn[x * 4 + 13];

                b_vals[0] = (INT32)(UINT8)rowIn[x * 4 + 2];
                b_vals[1] = (INT32)(UINT8)rowIn[x * 4 + 6];
                b_vals[2] = (INT32)(UINT8)rowIn[x * 4 + 10];
                b_vals[3] = (INT32)(UINT8)rowIn[x * 4 + 14];

                /* Compute indices and shifts */
                for (int i = 0; i < 4; i++) {
                    UINT32 r_scaled = r_vals[i] * scale1D;
                    UINT32 g_scaled = g_vals[i] * scale2D;
                    UINT32 b_scaled = b_vals[i] * scale3D;

                    idx1D_fixed_arr[i] = r_scaled >> SCALE_BITS;
                    idx2D_fixed_arr[i] = g_scaled >> SCALE_BITS;
                    idx3D_fixed_arr[i] = b_scaled >> SCALE_BITS;

                    shift1D_arr[i] = (SCALE_MASK & r_scaled) >> (SCALE_BITS - SHIFT_BITS);
                    shift2D_arr[i] = (SCALE_MASK & g_scaled) >> (SCALE_BITS - SHIFT_BITS);
                    shift3D_arr[i] = (SCALE_MASK & b_scaled) >> (SCALE_BITS - SHIFT_BITS);
                }

                /* Process 4 pixels */
                INT16 result_r[4], result_g[4], result_b[4];
                INT16 left[4], right[4];
                INT16 leftleft[4], leftright[4], rightleft[4], rightright[4];

                for (int i = 0; i < 4; i++) {
                    INT16 shift1D = shift1D_arr[i];
                    INT16 shift2D = shift2D_arr[i];
                    INT16 shift3D = shift3D_arr[i];
                    int i1 = idx1D_fixed_arr[i];
                    int i2 = idx2D_fixed_arr[i];
                    int i3 = idx3D_fixed_arr[i];

                    int idx = table_channels * (i1 + i2 * size1D + i3 * size1D_2D);

                    /* Interpolate along R axis */
                    interpolate3(leftleft, &table[idx], &table[idx + 3], shift1D);
                    interpolate3(leftright, &table[idx + size1D * 3], &table[idx + size1D * 3 + 3], shift1D);
                    /* Interpolate along G axis */
                    interpolate3(left, leftleft, leftright, shift2D);

                    /* Interpolate along R axis for layer 2 */
                    interpolate3(rightleft, &table[idx + size1D_2D * 3], &table[idx + size1D_2D * 3 + 3], shift1D);
                    interpolate3(rightright, &table[idx + size1D_2D * 3 + size1D * 3], &table[idx + size1D_2D * 3 + size1D * 3 + 3], shift1D);
                    /* Interpolate along G axis for layer 2 */
                    interpolate3(right, rightleft, rightright, shift2D);

                    /* Interpolate along B axis */
                    interpolate3(result, left, right, shift3D);

                    result_r[i] = result[0];
                    result_g[i] = result[1];
                    result_b[i] = result[2];
                }

                /* Pack results back into output */
                for (int i = 0; i < 4; i++) {
                    rowOut[(x + i) * 4 + 0] = clip8(result_r[i]);
                    rowOut[(x + i) * 4 + 1] = clip8(result_g[i]);
                    rowOut[(x + i) * 4 + 2] = clip8(result_b[i]);
                    rowOut[(x + i) * 4 + 3] = rowIn[(x + i) * 4 + 3];
                }
            }

            /* Handle remaining pixels (scalar fallback) */
            for (int x = xsize_simd; x < imOut->xsize; x++) {
                UINT32 index1D = rowIn[x * 4 + 0] * scale1D;
                UINT32 index2D = rowIn[x * 4 + 1] * scale2D;
                UINT32 index3D = rowIn[x * 4 + 2] * scale3D;
                INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);
                int idx = table_channels * table_index3D(
                                               index1D >> SCALE_BITS,
                                               index2D >> SCALE_BITS,
                                               index3D >> SCALE_BITS,
                                               size1D,
                                               size1D_2D);
                INT16 result[4], left[4], right[4];
                INT16 leftleft[4], leftright[4], rightleft[4], rightright[4];

                interpolate3(leftleft, &table[idx + 0], &table[idx + 3], shift1D);
                interpolate3(leftright, &table[idx + size1D * 3], &table[idx + size1D * 3 + 3], shift1D);
                interpolate3(left, leftleft, leftright, shift2D);

                interpolate3(rightleft, &table[idx + size1D_2D * 3], &table[idx + size1D_2D * 3 + 3], shift1D);
                interpolate3(rightright, &table[idx + size1D_2D * 3 + size1D * 3], &table[idx + size1D_2D * 3 + size1D * 3 + 3], shift1D);
                interpolate3(right, rightleft, rightright, shift2D);

                interpolate3(result, left, right, shift3D);

                rowOut[x * 4 + 0] = clip8(result[0]);
                rowOut[x * 4 + 1] = clip8(result[1]);
                rowOut[x * 4 + 2] = clip8(result[2]);
                rowOut[x * 4 + 3] = rowIn[x * 4 + 3];
            }
        }
    } else {
        /* 4 channels - use scalar fallback for now */
        for (y = 0; y < imOut->ysize; y++) {
            UINT8 *rowIn = (UINT8 *)imIn->image[y];
            char *rowOut = (char *)imOut->image[y];
            for (int x = 0; x < imOut->xsize; x++) {
                UINT32 index1D = rowIn[x * 4 + 0] * scale1D;
                UINT32 index2D = rowIn[x * 4 + 1] * scale2D;
                UINT32 index3D = rowIn[x * 4 + 2] * scale3D;
                INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);
                int idx = table_channels * table_index3D(
                                               index1D >> SCALE_BITS,
                                               index2D >> SCALE_BITS,
                                               index3D >> SCALE_BITS,
                                               size1D,
                                               size1D_2D);
                INT16 result[4], left[4], right[4];
                INT16 leftleft[4], leftright[4], rightleft[4], rightright[4];

                interpolate4(leftleft, &table[idx + 0], &table[idx + 4], shift1D);
                interpolate4(leftright, &table[idx + size1D * 4], &table[idx + size1D * 4 + 4], shift1D);
                interpolate4(left, leftleft, leftright, shift2D);

                interpolate4(rightleft, &table[idx + size1D_2D * 4], &table[idx + size1D_2D * 4 + 4], shift1D);
                interpolate4(rightright, &table[idx + size1D_2D * 4 + size1D * 4], &table[idx + size1D_2D * 4 + size1D * 4 + 4], shift1D);
