#include "Imaging.h"
#include <math.h>

/* 8 bits for result. Table can overflow [0, 1.0] range,
   so we need extra bits for overflow and negative values.
   NOTE: This value should be the same as in _imaging/_prepare_lut_table() */
#define PRECISION_BITS (16 - 8 - 2)
#define PRECISION_ROUNDING (1 << (PRECISION_BITS - 1))

/* 8 - scales are multiplied on byte.
   6 - max index in the table
       (max size is 65, but index 64 is not reachable) */
#define SCALE_BITS (32 - 8 - 6)
#define SCALE_MASK ((1 << SCALE_BITS) - 1)

#define SHIFT_BITS (16 - 1)

static inline UINT8
clip8(int in) {
    return clip8_lookups[(in + PRECISION_ROUNDING) >> PRECISION_BITS];
}

/*
 * Optimized scalar version with loop unrolling and reduced overhead.
 * Processes 4 pixels per iteration when possible.
 */
Imaging
ImagingColorLUT3D_linear(
    Imaging imOut,
    Imaging imIn,
    int table_channels,
    int size1D,
    int size2D,
    int size3D,
    INT16 *table) {

    UINT32 scale1D = (size1D - 1) / 255.0 * (1 << SCALE_BITS);
    UINT32 scale2D = (size2D - 1) / 255.0 * (1 << SCALE_BITS);
    UINT32 scale3D = (size3D - 1) / 255.0 * (1 << SCALE_BITS);
    int size1D_2D = size1D * size2D;
    int size1D_3 = size1D * 3;
    int size1D_2D_3 = size1D_2D * 3;
    int x, y;
    ImagingSectionCookie cookie;

    if (table_channels < 3 || table_channels > 4) {
        PyErr_SetString(PyExc_ValueError, "table_channels could be 3 or 4");
        return NULL;
    }

    if (imIn->type != IMAGING_TYPE_UINT8 || imOut->type != IMAGING_TYPE_UINT8 ||
        imIn->bands < 3 || imOut->bands < table_channels) {
        return (Imaging)ImagingError_ModeError();
    }

    if (imOut->bands > table_channels && imOut->bands > imIn->bands) {
        return (Imaging)ImagingError_ModeError();
    }

    ImagingSectionEnter(&cookie);

    if (table_channels == 3) {
        for (y = 0; y < imOut->ysize; y++) {
            UINT8 *rowIn = (UINT8 *)imIn->image[y];
            UINT8 *rowOut = (UINT8 *)imOut->image[y];

            /* Process 4 pixels at a time when possible */
            int xmax = imOut->xsize - 3;  /* Process 4 pixels starting at x, so last start is xsize - 4 */

            for (x = 0; x < xmax; x += 4) {
                UINT32 index1D_0 = rowIn[x * 4 + 0] * scale1D;
                UINT32 index1D_1 = rowIn[(x + 1) * 4 + 0] * scale1D;
                UINT32 index1D_2 = rowIn[(x + 2) * 4 + 0] * scale1D;
                UINT32 index1D_3 = rowIn[(x + 3) * 4 + 0] * scale1D;

                UINT32 index2D_0 = rowIn[x * 4 + 1] * scale2D;
                UINT32 index2D_1 = rowIn[(x + 1) * 4 + 1] * scale2D;
                UINT32 index2D_2 = rowIn[(x + 2) * 4 + 1] * scale2D;
                UINT32 index2D_3 = rowIn[(x + 3) * 4 + 1] * scale2D;

                UINT32 index3D_0 = rowIn[x * 4 + 2] * scale3D;
                UINT32 index3D_1 = rowIn[(x + 1) * 4 + 2] * scale3D;
                UINT32 index3D_2 = rowIn[(x + 2) * 4 + 2] * scale3D;
                UINT32 index3D_3 = rowIn[(x + 3) * 4 + 2] * scale3D;

                INT16 shift1D_0 = (SCALE_MASK & index1D_0) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift1D_1 = (SCALE_MASK & index1D_1) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift1D_2 = (SCALE_MASK & index1D_2) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift1D_3 = (SCALE_MASK & index1D_3) >> (SCALE_BITS - SHIFT_BITS);

                INT16 shift2D_0 = (SCALE_MASK & index2D_0) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D_1 = (SCALE_MASK & index2D_1) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D_2 = (SCALE_MASK & index2D_2) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D_3 = (SCALE_MASK & index2D_3) >> (SCALE_BITS - SHIFT_BITS);

                INT16 shift3D_0 = (SCALE_MASK & index3D_0) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D_1 = (SCALE_MASK & index3D_1) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D_2 = (SCALE_MASK & index3D_2) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D_3 = (SCALE_MASK & index3D_3) >> (SCALE_BITS - SHIFT_BITS);

                INT32 i1_0 = index1D_0 >> SCALE_BITS;
                INT32 i1_1 = index1D_1 >> SCALE_BITS;
                INT32 i1_2 = index1D_2 >> SCALE_BITS;
                INT32 i1_3 = index1D_3 >> SCALE_BITS;

                INT32 i2_0 = index2D_0 >> SCALE_BITS;
                INT32 i2_1 = index2D_1 >> SCALE_BITS;
                INT32 i2_2 = index2D_2 >> SCALE_BITS;
                INT32 i2_3 = index2D_3 >> SCALE_BITS;

                INT32 i3_0 = index3D_0 >> SCALE_BITS;
                INT32 i3_1 = index3D_1 >> SCALE_BITS;
                INT32 i3_2 = index3D_2 >> SCALE_BITS;
                INT32 i3_3 = index3D_3 >> SCALE_BITS;

                INT32 idx_0 = (i1_0 + i2_0 * size1D + i3_0 * size1D_2D) * 3;
                INT32 idx_1 = (i1_1 + i2_1 * size1D + i3_1 * size1D_2D) * 3;
                INT32 idx_2 = (i1_2 + i2_2 * size1D + i3_2 * size1D_2D) * 3;
                INT32 idx_3 = (i1_3 + i2_3 * size1D + i3_3 * size1D_2D) * 3;

                /* Process pixel 0 */
                {
                    INT16 *t0 = &table[idx_0];
                    INT16 shift1D = shift1D_0;
                    INT16 shift2D = shift2D_0;
                    INT16 shift3D = shift3D_0;
                    INT16 result[3], left[3], right[3];
                    INT16 leftleft[3], leftright[3], rightleft[3], rightright[3];

                    /* Interpolate along R axis */
                    leftleft[0] = (t0[0] * ((1 << SHIFT_BITS) - shift1D) + t0[3] * shift1D) >> SHIFT_BITS;
                    leftleft[1] = (t0[1] * ((1 << SHIFT_BITS) - shift1D) + t0[4] * shift1D) >> SHIFT_BITS;
                    leftleft[2] = (t0[2] * ((1 << SHIFT_BITS) - shift1D) + t0[5] * shift1D) >> SHIFT_BITS;

                    leftright[0] = (t0[size1D_3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_3 + 3] * shift1D) >> SHIFT_BITS;
                    leftright[1] = (t0[size1D_3 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_3 + 4] * shift1D) >> SHIFT_BITS;
                    leftright[2] = (t0[size1D_3 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_3 + 5] * shift1D) >> SHIFT_BITS;

                    /* Interpolate along G axis */
                    left[0] = (leftleft[0] * ((1 << SHIFT_BITS) - shift2D) + leftright[0] * shift2D) >> SHIFT_BITS;
                    left[1] = (leftleft[1] * ((1 << SHIFT_BITS) - shift2D) + leftright[1] * shift2D) >> SHIFT_BITS;
                    left[2] = (leftleft[2] * ((1 << SHIFT_BITS) - shift2D) + leftright[2] * shift2D) >> SHIFT_BITS;

                    /* Interpolate along R axis for layer 2 */
                    rightleft[0] = (t0[size1D_2D_3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + 3] * shift1D) >> SHIFT_BITS;
                    rightleft[1] = (t0[size1D_2D_3 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + 4] * shift1D) >> SHIFT_BITS;
                    rightleft[2] = (t0[size1D_2D_3 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + 5] * shift1D) >> SHIFT_BITS;

                    rightright[0] = (t0[size1D_2D_3 + size1D_3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + size1D_3 + 3] * shift1D) >> SHIFT_BITS;
                    rightright[1] = (t0[size1D_2D_3 + size1D_3 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + size1D_3 + 4] * shift1D) >> SHIFT_BITS;
                    rightright[2] = (t0[size1D_2D_3 + size1D_3 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + size1D_3 + 5] * shift1D) >> SHIFT_BITS;

                    /* Interpolate along G axis for layer 2 */
                    right[0] = (rightleft[0] * ((1 << SHIFT_BITS) - shift2D) + rightright[0] * shift2D) >> SHIFT_BITS;
                    right[1] = (rightleft[1] * ((1 << SHIFT_BITS) - shift2D) + rightright[1] * shift2D) >> SHIFT_BITS;
                    right[2] = (rightleft[2] * ((1 << SHIFT_BITS) - shift2D) + rightright[2] * shift2D) >> SHIFT_BITS;

                    /* Interpolate along B axis */
                    result[0] = (left[0] * ((1 << SHIFT_BITS) - shift3D) + right[0] * shift3D) >> SHIFT_BITS;
                    result[1] = (left[1] * ((1 << SHIFT_BITS) - shift3D) + right[1] * shift3D) >> SHIFT_BITS;
                    result[2] = (left[2] * ((1 << SHIFT_BITS) - shift3D) + right[2] * shift3D) >> SHIFT_BITS;

                    rowOut[x * 4 + 0] = clip8(result[0]);
                    rowOut[x * 4 + 1] = clip8(result[1]);
                    rowOut[x * 4 + 2] = clip8(result[2]);
                    rowOut[x * 4 + 3] = rowIn[x * 4 + 3];
                }

                /* Process pixel 1 */
                {
                    INT16 *t0 = &table[idx_1];
                    INT16 shift1D = shift1D_1;
                    INT16 shift2D = shift2D_1;
                    INT16 shift3D = shift3D_1;
                    INT16 result[3], left[3], right[3];
                    INT16 leftleft[3], leftright[3], rightleft[3], rightright[3];

                    leftleft[0] = (t0[0] * ((1 << SHIFT_BITS) - shift1D) + t0[3] * shift1D) >> SHIFT_BITS;
                    leftleft[1] = (t0[1] * ((1 << SHIFT_BITS) - shift1D) + t0[4] * shift1D) >> SHIFT_BITS;
                    leftleft[2] = (t0[2] * ((1 << SHIFT_BITS) - shift1D) + t0[5] * shift1D) >> SHIFT_BITS;

                    leftright[0] = (t0[size1D_3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_3 + 3] * shift1D) >> SHIFT_BITS;
                    leftright[1] = (t0[size1D_3 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_3 + 4] * shift1D) >> SHIFT_BITS;
                    leftright[2] = (t0[size1D_3 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_3 + 5] * shift1D) >> SHIFT_BITS;

                    left[0] = (leftleft[0] * ((1 << SHIFT_BITS) - shift2D) + leftright[0] * shift2D) >> SHIFT_BITS;
                    left[1] = (leftleft[1] * ((1 << SHIFT_BITS) - shift2D) + leftright[1] * shift2D) >> SHIFT_BITS;
                    left[2] = (leftleft[2] * ((1 << SHIFT_BITS) - shift2D) + leftright[2] * shift2D) >> SHIFT_BITS;

                    rightleft[0] = (t0[size1D_2D_3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + 3] * shift1D) >> SHIFT_BITS;
                    rightleft[1] = (t0[size1D_2D_3 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + 4] * shift1D) >> SHIFT_BITS;
                    rightleft[2] = (t0[size1D_2D_3 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + 5] * shift1D) >> SHIFT_BITS;

                    rightright[0] = (t0[size1D_2D_3 + size1D_3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + size1D_3 + 3] * shift1D) >> SHIFT_BITS;
                    rightright[1] = (t0[size1D_2D_3 + size1D_3 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + size1D_3 + 4] * shift1D) >> SHIFT_BITS;
                    rightright[2] = (t0[size1D_2D_3 + size1D_3 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + size1D_3 + 5] * shift1D) >> SHIFT_BITS;

                    right[0] = (rightleft[0] * ((1 << SHIFT_BITS) - shift2D) + rightright[0] * shift2D) >> SHIFT_BITS;
                    right[1] = (rightleft[1] * ((1 << SHIFT_BITS) - shift2D) + rightright[1] * shift2D) >> SHIFT_BITS;
                    right[2] = (rightleft[2] * ((1 << SHIFT_BITS) - shift2D) + rightright[2] * shift2D) >> SHIFT_BITS;

                    result[0] = (left[0] * ((1 << SHIFT_BITS) - shift3D) + right[0] * shift3D) >> SHIFT_BITS;
                    result[1] = (left[1] * ((1 << SHIFT_BITS) - shift3D) + right[1] * shift3D) >> SHIFT_BITS;
                    result[2] = (left[2] * ((1 << SHIFT_BITS) - shift3D) + right[2] * shift3D) >> SHIFT_BITS;

                    rowOut[(x + 1) * 4 + 0] = clip8(result[0]);
                    rowOut[(x + 1) * 4 + 1] = clip8(result[1]);
                    rowOut[(x + 1) * 4 + 2] = clip8(result[2]);
                    rowOut[(x + 1) * 4 + 3] = rowIn[(x + 1) * 4 + 3];
                }

                /* Process pixel 2 */
                {
                    INT16 *t0 = &table[idx_2];
                    INT16 shift1D = shift1D_2;
                    INT16 shift2D = shift2D_2;
                    INT16 shift3D = shift3D_2;
                    INT16 result[3], left[3], right[3];
                    INT16 leftleft[3], leftright[3], rightleft[3], rightright[3];

                    leftleft[0] = (t0[0] * ((1 << SHIFT_BITS) - shift1D) + t0[3] * shift1D) >> SHIFT_BITS;
                    leftleft[1] = (t0[1] * ((1 << SHIFT_BITS) - shift1D) + t0[4] * shift1D) >> SHIFT_BITS;
                    leftleft[2] = (t0[2] * ((1 << SHIFT_BITS) - shift1D) + t0[5] * shift1D) >> SHIFT_BITS;

                    leftright[0] = (t0[size1D_3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_3 + 3] * shift1D) >> SHIFT_BITS;
                    leftright[1] = (t0[size1D_3 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_3 + 4] * shift1D) >> SHIFT_BITS;
                    leftright[2] = (t0[size1D_3 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_3 + 5] * shift1D) >> SHIFT_BITS;

                    left[0] = (leftleft[0] * ((1 << SHIFT_BITS) - shift2D) + leftright[0] * shift2D) >> SHIFT_BITS;
                    left[1] = (leftleft[1] * ((1 << SHIFT_BITS) - shift2D) + leftright[1] * shift2D) >> SHIFT_BITS;
                    left[2] = (leftleft[2] * ((1 << SHIFT_BITS) - shift2D) + leftright[2] * shift2D) >> SHIFT_BITS;

                    rightleft[0] = (t0[size1D_2D_3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + 3] * shift1D) >> SHIFT_BITS;
                    rightleft[1] = (t0[size1D_2D_3 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + 4] * shift1D) >> SHIFT_BITS;
                    rightleft[2] = (t0[size1D_2D_3 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + 5] * shift1D) >> SHIFT_BITS;

                    rightright[0] = (t0[size1D_2D_3 + size1D_3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + size1D_3 + 3] * shift1D) >> SHIFT_BITS;
                    rightright[1] = (t0[size1D_2D_3 + size1D_3 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + size1D_3 + 4] * shift1D) >> SHIFT_BITS;
                    rightright[2] = (t0[size1D_2D_3 + size1D_3 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + size1D_3 + 5] * shift1D) >> SHIFT_BITS;

                    right[0] = (rightleft[0] * ((1 << SHIFT_BITS) - shift2D) + rightright[0] * shift2D) >> SHIFT_BITS;
                    right[1] = (rightleft[1] * ((1 << SHIFT_BITS) - shift2D) + rightright[1] * shift2D) >> SHIFT_BITS;
                    right[2] = (rightleft[2] * ((1 << SHIFT_BITS) - shift2D) + rightright[2] * shift2D) >> SHIFT_BITS;

                    result[0] = (left[0] * ((1 << SHIFT_BITS) - shift3D) + right[0] * shift3D) >> SHIFT_BITS;
                    result[1] = (left[1] * ((1 << SHIFT_BITS) - shift3D) + right[1] * shift3D) >> SHIFT_BITS;
                    result[2] = (left[2] * ((1 << SHIFT_BITS) - shift3D) + right[2] * shift3D) >> SHIFT_BITS;

                    rowOut[(x + 2) * 4 + 0] = clip8(result[0]);
                    rowOut[(x + 2) * 4 + 1] = clip8(result[1]);
                    rowOut[(x + 2) * 4 + 2] = clip8(result[2]);
                    rowOut[(x + 2) * 4 + 3] = rowIn[(x + 2) * 4 + 3];
                }

                /* Process pixel 3 */
                {
                    INT16 *t0 = &table[idx_3];
                    INT16 shift1D = shift1D_3;
                    INT16 shift2D = shift2D_3;
                    INT16 shift3D = shift3D_3;
                    INT16 result[3], left[3], right[3];
                    INT16 leftleft[3], leftright[3], rightleft[3], rightright[3];

                    leftleft[0] = (t0[0] * ((1 << SHIFT_BITS) - shift1D) + t0[3] * shift1D) >> SHIFT_BITS;
                    leftleft[1] = (t0[1] * ((1 << SHIFT_BITS) - shift1D) + t0[4] * shift1D) >> SHIFT_BITS;
                    leftleft[2] = (t0[2] * ((1 << SHIFT_BITS) - shift1D) + t0[5] * shift1D) >> SHIFT_BITS;

                    leftright[0] = (t0[size1D_3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_3 + 3] * shift1D) >> SHIFT_BITS;
                    leftright[1] = (t0[size1D_3 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_3 + 4] * shift1D) >> SHIFT_BITS;
                    leftright[2] = (t0[size1D_3 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_3 + 5] * shift1D) >> SHIFT_BITS;

                    left[0] = (leftleft[0] * ((1 << SHIFT_BITS) - shift2D) + leftright[0] * shift2D) >> SHIFT_BITS;
                    left[1] = (leftleft[1] * ((1 << SHIFT_BITS) - shift2D) + leftright[1] * shift2D) >> SHIFT_BITS;
                    left[2] = (leftleft[2] * ((1 << SHIFT_BITS) - shift2D) + leftright[2] * shift2D) >> SHIFT_BITS;

                    rightleft[0] = (t0[size1D_2D_3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + 3] * shift1D) >> SHIFT_BITS;
                    rightleft[1] = (t0[size1D_2D_3 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + 4] * shift1D) >> SHIFT_BITS;
                    rightleft[2] = (t0[size1D_2D_3 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + 5] * shift1D) >> SHIFT_BITS;

                    rightright[0] = (t0[size1D_2D_3 + size1D_3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + size1D_3 + 3] * shift1D) >> SHIFT_BITS;
                    rightright[1] = (t0[size1D_2D_3 + size1D_3 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + size1D_3 + 4] * shift1D) >> SHIFT_BITS;
                    rightright[2] = (t0[size1D_2D_3 + size1D_3 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + size1D_3 + 5] * shift1D) >> SHIFT_BITS;

                    right[0] = (rightleft[0] * ((1 << SHIFT_BITS) - shift2D) + rightright[0] * shift2D) >> SHIFT_BITS;
                    right[1] = (rightleft[1] * ((1 << SHIFT_BITS) - shift2D) + rightright[1] * shift2D) >> SHIFT_BITS;
                    right[2] = (rightleft[2] * ((1 << SHIFT_BITS) - shift2D) + rightright[2] * shift2D) >> SHIFT_BITS;

                    result[0] = (left[0] * ((1 << SHIFT_BITS) - shift3D) + right[0] * shift3D) >> SHIFT_BITS;
                    result[1] = (left[1] * ((1 << SHIFT_BITS) - shift3D) + right[1] * shift3D) >> SHIFT_BITS;
                    result[2] = (left[2] * ((1 << SHIFT_BITS) - shift3D) + right[2] * shift3D) >> SHIFT_BITS;

                    rowOut[(x + 3) * 4 + 0] = clip8(result[0]);
                    rowOut[(x + 3) * 4 + 1] = clip8(result[1]);
                    rowOut[(x + 3) * 4 + 2] = clip8(result[2]);
                    rowOut[(x + 3) * 4 + 3] = rowIn[(x + 3) * 4 + 3];
                }
            }

            /* Handle remaining pixels */
            for (; x < imOut->xsize; x++) {
                UINT32 index1D = rowIn[x * 4 + 0] * scale1D;
                UINT32 index2D = rowIn[x * 4 + 1] * scale2D;
                UINT32 index3D = rowIn[x * 4 + 2] * scale3D;
                INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);
                INT32 i1 = index1D >> SCALE_BITS;
                INT32 i2 = index2D >> SCALE_BITS;
                INT32 i3 = index3D >> SCALE_BITS;
                INT32 idx = (i1 + i2 * size1D + i3 * size1D_2D) * 3;
                INT16 *t0 = &table[idx];

                INT16 result[3], left[3], right[3];
                INT16 leftleft[3], leftright[3], rightleft[3], rightright[3];

                leftleft[0] = (t0[0] * ((1 << SHIFT_BITS) - shift1D) + t0[3] * shift1D) >> SHIFT_BITS;
                leftleft[1] = (t0[1] * ((1 << SHIFT_BITS) - shift1D) + t0[4] * shift1D) >> SHIFT_BITS;
                leftleft[2] = (t0[2] * ((1 << SHIFT_BITS) - shift1D) + t0[5] * shift1D) >> SHIFT_BITS;

                leftright[0] = (t0[size1D_3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_3 + 3] * shift1D) >> SHIFT_BITS;
                leftright[1] = (t0[size1D_3 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_3 + 4] * shift1D) >> SHIFT_BITS;
                leftright[2] = (t0[size1D_3 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_3 + 5] * shift1D) >> SHIFT_BITS;

                left[0] = (leftleft[0] * ((1 << SHIFT_BITS) - shift2D) + leftright[0] * shift2D) >> SHIFT_BITS;
                left[1] = (leftleft[1] * ((1 << SHIFT_BITS) - shift2D) + leftright[1] * shift2D) >> SHIFT_BITS;
                left[2] = (leftleft[2] * ((1 << SHIFT_BITS) - shift2D) + leftright[2] * shift2D) >> SHIFT_BITS;

                rightleft[0] = (t0[size1D_2D_3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + 3] * shift1D) >> SHIFT_BITS;
                rightleft[1] = (t0[size1D_2D_3 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + 4] * shift1D) >> SHIFT_BITS;
                rightleft[2] = (t0[size1D_2D_3 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + 5] * shift1D) >> SHIFT_BITS;

                rightright[0] = (t0[size1D_2D_3 + size1D_3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + size1D_3 + 3] * shift1D) >> SHIFT_BITS;
                rightright[1] = (t0[size1D_2D_3 + size1D_3 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + size1D_3 + 4] * shift1D) >> SHIFT_BITS;
                rightright[2] = (t0[size1D_2D_3 + size1D_3 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D_3 + size1D_3 + 5] * shift1D) >> SHIFT_BITS;

                right[0] = (rightleft[0] * ((1 << SHIFT_BITS) - shift2D) + rightright[0] * shift2D) >> SHIFT_BITS;
                right[1] = (rightleft[1] * ((1 << SHIFT_BITS) - shift2D) + rightright[1] * shift2D) >> SHIFT_BITS;
                right[2] = (rightleft[2] * ((1 << SHIFT_BITS) - shift2D) + rightright[2] * shift2D) >> SHIFT_BITS;

                result[0] = (left[0] * ((1 << SHIFT_BITS) - shift3D) + right[0] * shift3D) >> SHIFT_BITS;
                result[1] = (left[1] * ((1 << SHIFT_BITS) - shift3D) + right[1] * shift3D) >> SHIFT_BITS;
                result[2] = (left[2] * ((1 << SHIFT_BITS) - shift3D) + right[2] * shift3D) >> SHIFT_BITS;

                rowOut[x * 4 + 0] = clip8(result[0]);
                rowOut[x * 4 + 1] = clip8(result[1]);
                rowOut[x * 4 + 2] = clip8(result[2]);
                rowOut[x * 4 + 3] = rowIn[x * 4 + 3];
            }
        }
    } else {
        /* 4 channels - scalar fallback */
        for (y = 0; y < imOut->ysize; y++) {
            UINT8 *rowIn = (UINT8 *)imIn->image[y];
            char *rowOut = (char *)imOut->image[y];
            for (x = 0; x < imOut->xsize; x++) {
                UINT32 index1D = rowIn[x * 4 + 0] * scale1D;
                UINT32 index2D = rowIn[x * 4 + 1] * scale2D;
                UINT32 index3D = rowIn[x * 4 + 2] * scale3D;
                INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);
                INT32 i1 = index1D >> SCALE_BITS;
                INT32 i2 = index2D >> SCALE_BITS;
                INT32 i3 = index3D >> SCALE_BITS;
                INT32 idx = (i1 + i2 * size1D + i3 * size1D_2D) * 4;
                INT16 *t0 = &table[idx];

                INT16 result[4], left[4], right[4];
                INT16 leftleft[4], leftright[4], rightleft[4], rightright[4];

                /* Interpolate along R */
                leftleft[0] = (t0[0] * ((1 << SHIFT_BITS) - shift1D) + t0[4] * shift1D) >> SHIFT_BITS;
                leftleft[1] = (t0[1] * ((1 << SHIFT_BITS) - shift1D) + t0[5] * shift1D) >> SHIFT_BITS;
                leftleft[2] = (t0[2] * ((1 << SHIFT_BITS) - shift1D) + t0[6] * shift1D) >> SHIFT_BITS;
                leftleft[3] = (t0[3] * ((1 << SHIFT_BITS) - shift1D) + t0[7] * shift1D) >> SHIFT_BITS;

                leftright[0] = (t0[size1D * 4] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D * 4 + 4] * shift1D) >> SHIFT_BITS;
                leftright[1] = (t0[size1D * 4 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D * 4 + 5] * shift1D) >> SHIFT_BITS;
                leftright[2] = (t0[size1D * 4 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D * 4 + 6] * shift1D) >> SHIFT_BITS;
                leftright[3] = (t0[size1D * 4 + 3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D * 4 + 7] * shift1D) >> SHIFT_BITS;

                left[0] = (leftleft[0] * ((1 << SHIFT_BITS) - shift2D) + leftright[0] * shift2D) >> SHIFT_BITS;
                left[1] = (leftleft[1] * ((1 << SHIFT_BITS) - shift2D) + leftright[1] * shift2D) >> SHIFT_BITS;
                left[2] = (leftleft[2] * ((1 << SHIFT_BITS) - shift2D) + leftright[2] * shift2D) >> SHIFT_BITS;
                left[3] = (leftleft[3] * ((1 << SHIFT_BITS) - shift2D) + leftright[3] * shift2D) >> SHIFT_BITS;

                rightleft[0] = (t0[size1D_2D * 4] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D * 4 + 4] * shift1D) >> SHIFT_BITS;
                rightleft[1] = (t0[size1D_2D * 4 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D * 4 + 5] * shift1D) >> SHIFT_BITS;
                rightleft[2] = (t0[size1D_2D * 4 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D * 4 + 6] * shift1D) >> SHIFT_BITS;
                rightleft[3] = (t0[size1D_2D * 4 + 3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D * 4 + 7] * shift1D) >> SHIFT_BITS;

                rightright[0] = (t0[size1D_2D * 4 + size1D * 4] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D * 4 + size1D * 4 + 4] * shift1D) >> SHIFT_BITS;
                rightright[1] = (t0[size1D_2D * 4 + size1D * 4 + 1] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D * 4 + size1D * 4 + 5] * shift1D) >> SHIFT_BITS;
                rightright[2] = (t0[size1D_2D * 4 + size1D * 4 + 2] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D * 4 + size1D * 4 + 6] * shift1D) >> SHIFT_BITS;
                rightright[3] = (t0[size1D_2D * 4 + size1D * 4 + 3] * ((1 << SHIFT_BITS) - shift1D) + t0[size1D_2D * 4 + size1D * 4 + 7] * shift1D) >> SHIFT_BITS;

                right[0] = (rightleft[0] * ((1 << SHIFT_BITS) - shift2D) + rightright[0] * shift2D) >> SHIFT_BITS;
                right[1] = (rightleft[1] * ((1 << SHIFT_BITS) - shift2D) + rightright[1] * shift2D) >> SHIFT_BITS;
                right[2] = (rightleft[2] * ((1 << SHIFT_BITS) - shift2D) + rightright[2] * shift2D) >> SHIFT_BITS;
                right[3] = (rightleft[3] * ((1 << SHIFT_BITS) - shift2D) + rightright[3] * shift2D) >> SHIFT_BITS;

                result[0] = (left[0] * ((1 << SHIFT_BITS) - shift3D) + right[0] * shift3D) >> SHIFT_BITS;
                result[1] = (left[1] * ((1 << SHIFT_BITS) - shift3D) + right[1] * shift3D) >> SHIFT_BITS;
                result[2] = (left[2] * ((1 << SHIFT_BITS) - shift3D) + right[2] * shift3D) >> SHIFT_BITS;
                result[3] = (left[3] * ((1 << SHIFT_BITS) - shift3D) + right[3] * shift3D) >> SHIFT_BITS;

                UINT32 v = (clip8(result[0]) |
                           (clip8(result[1]) << 8) |
                           (clip8(result[2]) << 16) |
                           (clip8(result[3]) << 24));
                memcpy(rowOut + x * 4, &v, 4);
            }
        }
    }

    ImagingSectionLeave(&cookie);

    return imOut;
}

