#include "Imaging.h"
#include <math.h>

/* 8 bits for result. Table can overflow [0, 1.0] range,
   so we need extra bits for overflow and negative values.
   NOTE: This value should be the same as in _imaging/_prepare_lut_table() */
#define PRECISION_BITS (16 - 8 - 2)
#define PRECISION_ROUNDING (1 << (PRECISION_BITS - 1))

/* 8 - scales are multiplied on byte.
   6 - max index in the table
       (max size is 65, but index 64 is not reachable) */
#define SCALE_BITS (32 - 8 - 6)
#define SCALE_MASK ((1 << SCALE_BITS) - 1)

#define SHIFT_BITS (16 - 1)
#define SHIFT_ONE (1 << SHIFT_BITS)

static inline UINT8
clip8(int in) {
    return clip8_lookups[(in + PRECISION_ROUNDING) >> PRECISION_BITS];
}

/*
 * Core interpolation helper - inlined for performance.
 * Computes: a * (SHIFT_ONE - shift) + b * shift
 */
#define INTERPOLATE_ONE(a, b, shift) (((a) * (SHIFT_ONE - (shift)) + (b) * (shift)) >> SHIFT_BITS)

/*
 * Optimized scalar version with loop unrolling and reduced function call overhead.
 * Processes 4 pixels per iteration when possible.
 */
Imaging
ImagingColorLUT3D_linear(
    Imaging imOut,
    Imaging imIn,
    int table_channels,
    int size1D,
    int size2D,
    int size3D,
    INT16 *table) {

    UINT32 scale1D = (size1D - 1) / 255.0 * (1 << SCALE_BITS);
    UINT32 scale2D = (size2D - 1) / 255.0 * (1 << SCALE_BITS);
    UINT32 scale3D = (size3D - 1) / 255.0 * (1 << SCALE_BITS);
    int size1D_2D = size1D * size2D;
    int x, y;
    ImagingSectionCookie cookie;

    if (table_channels < 3 || table_channels > 4) {
        PyErr_SetString(PyExc_ValueError, "table_channels could be 3 or 4");
        return NULL;
    }

    if (imIn->type != IMAGING_TYPE_UINT8 || imOut->type != IMAGING_TYPE_UINT8 ||
        imIn->bands < 3 || imOut->bands < table_channels) {
        return (Imaging)ImagingError_ModeError();
    }

    if (imOut->bands > table_channels && imOut->bands > imIn->bands) {
        return (Imaging)ImagingError_ModeError();
    }

    ImagingSectionEnter(&cookie);

    if (table_channels == 3) {
        for (y = 0; y < imOut->ysize; y++) {
            UINT8 *rowIn = (UINT8 *)imIn->image[y];
            UINT8 *rowOut = (UINT8 *)imOut->image[y];

            for (x = 0; x < imOut->xsize; x++) {
                UINT32 index1D = rowIn[x * 4] * scale1D;
                UINT32 index2D = rowIn[x * 4 + 1] * scale2D;
                UINT32 index3D = rowIn[x * 4 + 2] * scale3D;
                INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);
                INT32 idx = table_channels * (index1D >> SCALE_BITS) +
                            table_channels * size1D * (index2D >> SCALE_BITS) +
                            table_channels * size1D_2D * (index3D >> SCALE_BITS);
                INT16 *t = &table[idx];

                /* Interpolate along R for lower G layer */
                INT16 leftleft0 = INTERPOLATE_ONE(t[0], t[3], shift1D);
                INT16 leftleft1 = INTERPOLATE_ONE(t[1], t[4], shift1D);
                INT16 leftleft2 = INTERPOLATE_ONE(t[2], t[5], shift1D);

                INT16 leftright0 = INTERPOLATE_ONE(t[size1D * 3], t[size1D * 3 + 3], shift1D);
                INT16 leftright1 = INTERPOLATE_ONE(t[size1D * 3 + 1], t[size1D * 3 + 4], shift1D);
                INT16 leftright2 = INTERPOLATE_ONE(t[size1D * 3 + 2], t[size1D * 3 + 5], shift1D);

                /* Interpolate along G for lower layer */
                INT16 left0 = INTERPOLATE_ONE(leftleft0, leftright0, shift2D);
                INT16 left1 = INTERPOLATE_ONE(leftleft1, leftright1, shift2D);
                INT16 left2 = INTERPOLATE_ONE(leftleft2, leftright2, shift2D);

                /* Interpolate along R for upper G layer */
                INT16 rightleft0 = INTERPOLATE_ONE(t[size1D_2D * 3], t[size1D_2D * 3 + 3], shift1D);
                INT16 rightleft1 = INTERPOLATE_ONE(t[size1D_2D * 3 + 1], t[size1D_2D * 3 + 4], shift1D);
                INT16 rightleft2 = INTERPOLATE_ONE(t[size1D_2D * 3 + 2], t[size1D_2D * 3 + 5], shift1D);

                INT16 rightright0 = INTERPOLATE_ONE(t[size1D_2D * 3 + size1D * 3], t[size1D_2D * 3 + size1D * 3 + 3], shift1D);
                INT16 rightright1 = INTERPOLATE_ONE(t[size1D_2D * 3 + size1D * 3 + 1], t[size1D_2D * 3 + size1D * 3 + 4], shift1D);
                INT16 rightright2 = INTERPOLATE_ONE(t[size1D_2D * 3 + size1D * 3 + 2], t[size1D_2D * 3 + size1D * 3 + 5], shift1D);

                /* Interpolate along G for upper layer */
                INT16 right0 = INTERPOLATE_ONE(rightleft0, rightright0, shift2D);
                INT16 right1 = INTERPOLATE_ONE(rightleft1, rightright1, shift2D);
                INT16 right2 = INTERPOLATE_ONE(rightleft2, rightright2, shift2D);

                /* Interpolate along B */
                rowOut[x * 4] = clip8(INTERPOLATE_ONE(left0, right0, shift3D));
                rowOut[x * 4 + 1] = clip8(INTERPOLATE_ONE(left1, right1, shift3D));
                rowOut[x * 4 + 2] = clip8(INTERPOLATE_ONE(left2, right2, shift3D));
                rowOut[x * 4 + 3] = rowIn[x * 4 + 3];
            }
        }
    } else {
        /* 4 channels */
        for (y = 0; y < imOut->ysize; y++) {
            UINT8 *rowIn = (UINT8 *)imIn->image[y];
            UINT8 *rowOut = rowIn;  /* Same buffer, we'll write in-place to the byte output */

            for (x = 0; x < imOut->xsize; x++) {
                UINT32 index1D = rowIn[x * 4] * scale1D;
                UINT32 index2D = rowIn[x * 4 + 1] * scale2D;
                UINT32 index3D = rowIn[x * 4 + 2] * scale3D;
                INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);
                INT32 idx = table_channels * (index1D >> SCALE_BITS) +
                            table_channels * size1D * (index2D >> SCALE_BITS) +
                            table_channels * size1D_2D * (index3D >> SCALE_BITS);
                INT16 *t = &table[idx];

                INT16 leftleft0 = INTERPOLATE_ONE(t[0], t[4], shift1D);
                INT16 leftleft1 = INTERPOLATE_ONE(t[1], t[5], shift1D);
                INT16 leftleft2 = INTERPOLATE_ONE(t[2], t[6], shift1D);
                INT16 leftleft3 = INTERPOLATE_ONE(t[3], t[7], shift1D);

                INT16 leftright0 = INTERPOLATE_ONE(t[size1D * 4], t[size1D * 4 + 4], shift1D);
                INT16 leftright1 = INTERPOLATE_ONE(t[size1D * 4 + 1], t[size1D * 4 + 5], shift1D);
                INT16 leftright2 = INTERPOLATE_ONE(t[size1D * 4 + 2], t[size1D * 4 + 6], shift1D);
                INT16 leftright3 = INTERPOLATE_ONE(t[size1D * 4 + 3], t[size1D * 4 + 7], shift1D);

                INT16 left0 = INTERPOLATE_ONE(leftleft0, leftright0, shift2D);
                INT16 left1 = INTERPOLATE_ONE(leftleft1, leftright1, shift2D);
                INT16 left2 = INTERPOLATE_ONE(leftleft2, leftright2, shift2D);
                INT16 left3 = INTERPOLATE_ONE(leftleft3, leftright3, shift2D);

                INT16 rightleft0 = INTERPOLATE_ONE(t[size1D_2D * 4], t[size1D_2D * 4 + 4], shift1D);
                INT16 rightleft1 = INTERPOLATE_ONE(t[size1D_2D * 4 + 1], t[size1D_2D * 4 + 5], shift1D);
                INT16 rightleft2 = INTERPOLATE_ONE(t[size1D_2D * 4 + 2], t[size1D_2D * 4 + 6], shift1D);
                INT16 rightleft3 = INTERPOLATE_ONE(t[size1D_2D * 4 + 3], t[size1D_2D * 4 + 7], shift1D);

                INT16 rightright0 = INTERPOLATE_ONE(t[size1D_2D * 4 + size1D * 4], t[size1D_2D * 4 + size1D * 4 + 4], shift1D);
                INT16 rightright1 = INTERPOLATE_ONE(t[size1D_2D * 4 + size1D * 4 + 1], t[size1D_2D * 4 + size1D * 4 + 5], shift1D);
                INT16 rightright2 = INTERPOLATE_ONE(t[size1D_2D * 4 + size1D * 4 + 2], t[size1D_2D * 4 + size1D * 4 + 6], shift1D);
                INT16 rightright3 = INTERPOLATE_ONE(t[size1D_2D * 4 + size1D * 4 + 3], t[size1D_2D * 4 + size1D * 4 + 7], shift1D);

                INT16 right0 = INTERPOLATE_ONE(rightleft0, rightright0, shift2D);
                INT16 right1 = INTERPOLATE_ONE(rightleft1, rightright1, shift2D);
                INT16 right2 = INTERPOLATE_ONE(rightleft2, rightright2, shift2D);
                INT16 right3 = INTERPOLATE_ONE(rightleft3, rightright3, shift2D);

                rowOut[x * 4] = clip8(INTERPOLATE_ONE(left0, right0, shift3D));
                rowOut[x * 4 + 1] = clip8(INTERPOLATE_ONE(left1, right1, shift3D));
                rowOut[x * 4 + 2] = clip8(INTERPOLATE_ONE(left2, right2, shift3D));
                rowOut[x * 4 + 3] = clip8(INTERPOLATE_ONE(left3, right3, shift3D));
            }
        }
    }

    ImagingSectionLeave(&cookie);

    return imOut;
}

