#include "Imaging.h"
#include <math.h>

/* 8 bits for result. Table can overflow [0, 1.0] range,
   so we need extra bits for overflow and negative values.
   NOTE: This value should be the same as in _imaging/_prepare_lut_table() */
#define PRECISION_BITS (16 - 8 - 2)
#define PRECISION_ROUNDING (1 << (PRECISION_BITS - 1))

/* 8 - scales are multiplied on byte.
   6 - max index in the table
       (max size is 65, but index 64 is not reachable) */
#define SCALE_BITS (32 - 8 - 6)
#define SCALE_MASK ((1 << SCALE_BITS) - 1)

#define SHIFT_BITS (16 - 1)
#define SHIFT_ONE (1 << SHIFT_BITS)

static inline UINT8
clip8(int in) {
    return clip8_lookups[(in + PRECISION_ROUNDING) >> PRECISION_BITS];
}

/*
 * Core interpolation helper - inlined for performance.
 */
static inline INT16
interp16(INT16 a, INT16 b, INT16 shift) {
    return (a * (SHIFT_ONE - shift) + b * shift) >> SHIFT_BITS;
}

/*
 * Optimized scalar version with inlined interpolation and optimized memory access.
 * The key optimizations are:
 * 1. Inlined interpolation (no function call overhead)
 * 2. Precomputed offsets for table access
 * 3. Direct memory writes instead of memcpy
 * 4. Reduced indexing overhead
 */
Imaging
ImagingColorLUT3D_linear(
    Imaging imOut,
    Imaging imIn,
    int table_channels,
    int size1D,
    int size2D,
    int size3D,
    INT16 *table) {

    UINT32 scale1D = (size1D - 1) / 255.0f * (1 << SCALE_BITS);
    UINT32 scale2D = (size2D - 1) / 255.0f * (1 << SCALE_BITS);
    UINT32 scale3D = (size3D - 1) / 255.0f * (1 << SCALE_BITS);
    int size1D_2D = size1D * size2D;
    int size1D_3 = size1D * 3;
    int size1D_2D_3 = size1D_2D * 3;
    int x, y;
    ImagingSectionCookie cookie;

    if (table_channels < 3 || table_channels > 4) {
        PyErr_SetString(PyExc_ValueError, "table_channels could be 3 or 4");
        return NULL;
    }

    if (imIn->type != IMAGING_TYPE_UINT8 || imOut->type != IMAGING_TYPE_UINT8 ||
        imIn->bands < 3 || imOut->bands < table_channels) {
        return (Imaging)ImagingError_ModeError();
    }

    if (imOut->bands > table_channels && imOut->bands > imIn->bands) {
        return (Imaging)ImagingError_ModeError();
    }

    ImagingSectionEnter(&cookie);

    if (table_channels == 3) {
        for (y = 0; y < imOut->ysize; y++) {
            UINT8 *rowIn = (UINT8 *)imIn->image[y];
            UINT8 *rowOut = (UINT8 *)imOut->image[y];
            int rowInOffset = 0;
            int rowOutOffset = 0;

            for (x = 0; x < imOut->xsize; x++) {
                UINT32 r = rowIn[rowInOffset];
                UINT32 g = rowIn[rowInOffset + 1];
                UINT32 b = rowIn[rowInOffset + 2];

                UINT32 index1D = r * scale1D;
                UINT32 index2D = g * scale2D;
                UINT32 index3D = b * scale3D;

                INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);

                INT32 idx1 = index1D >> SCALE_BITS;
                INT32 idx2 = index2D >> SCALE_BITS;
                INT32 idx3 = index3D >> SCALE_BITS;

                INT32 idx = idx1 + idx2 * size1D + idx3 * size1D_2D;
                INT16 *t = &table[idx * 3];

                /* Interpolate along R for lower G layer */
                INT16 ll0 = t[0] + ((t[3] - t[0]) * shift1D >> SHIFT_BITS);
                INT16 ll1 = t[1] + ((t[4] - t[1]) * shift1D >> SHIFT_BITS);
                INT16 ll2 = t[2] + ((t[5] - t[2]) * shift1D >> SHIFT_BITS);

                INT16 lr0 = t[size1D_3] + ((t[size1D_3 + 3] - t[size1D_3]) * shift1D >> SHIFT_BITS);
                INT16 lr1 = t[size1D_3 + 1] + ((t[size1D_3 + 4] - t[size1D_3 + 1]) * shift1D >> SHIFT_BITS);
                INT16 lr2 = t[size1D_3 + 2] + ((t[size1D_3 + 5] - t[size1D_3 + 2]) * shift1D >> SHIFT_BITS);

                /* Interpolate along G for lower layer */
                INT16 l0 = ll0 + ((lr0 - ll0) * shift2D >> SHIFT_BITS);
                INT16 l1 = ll1 + ((lr1 - ll1) * shift2D >> SHIFT_BITS);
                INT16 l2 = ll2 + ((lr2 - ll2) * shift2D >> SHIFT_BITS);

                /* Interpolate along R for upper G layer */
                INT16 rl0 = t[size1D_2D_3] + ((t[size1D_2D_3 + 3] - t[size1D_2D_3]) * shift1D >> SHIFT_BITS);
                INT16 rl1 = t[size1D_2D_3 + 1] + ((t[size1D_2D_3 + 4] - t[size1D_2D_3 + 1]) * shift1D >> SHIFT_BITS);
                INT16 rl2 = t[size1D_2D_3 + 2] + ((t[size1D_2D_3 + 5] - t[size1D_2D_3 + 2]) * shift1D >> SHIFT_BITS);

                INT16 rr0 = t[size1D_2D_3 + size1D_3] + ((t[size1D_2D_3 + size1D_3 + 3] - t[size1D_2D_3 + size1D_3]) * shift1D >> SHIFT_BITS);
                INT16 rr1 = t[size1D_2D_3 + size1D_3 + 1] + ((t[size1D_2D_3 + size1D_3 + 4] - t[size1D_2D_3 + size1D_3 + 1]) * shift1D >> SHIFT_BITS);
                INT16 rr2 = t[size1D_2D_3 + size1D_3 + 2] + ((t[size1D_2D_3 + size1D_3 + 5] - t[size1D_2D_3 + size1D_3 + 2]) * shift1D >> SHIFT_BITS);

                /* Interpolate along G for upper layer */
                INT16 r0 = rl0 + ((rr0 - rl0) * shift2D >> SHIFT_BITS);
                INT16 r1 = rl1 + ((rr1 - rl1) * shift2D >> SHIFT_BITS);
                INT16 r2 = rl2 + ((rr2 - rl2) * shift2D >> SHIFT_BITS);

