                INT16 result1 = (l1 * shift3D_inv + r1 * shift3D) >> SHIFT_BITS;
                INT16 result2 = (l2 * shift3D_inv + r2 * shift3D) >> SHIFT_BITS;

                /* Inline clip8 */
                rowOut[rowOutOffset] = clip8_lookups[(result0 + PRECISION_ROUNDING) >> PRECISION_BITS];
                rowOut[rowOutOffset + 1] = clip8_lookups[(result1 + PRECISION_ROUNDING) >> PRECISION_BITS];
                rowOut[rowOutOffset + 2] = clip8_lookups[(result2 + PRECISION_ROUNDING) >> PRECISION_BITS];
                rowOut[rowOutOffset + 3] = rowIn[rowInOffset + 3];

                rowInOffset += 4;
                rowOutOffset += 4;
            }
        }
    } else {
        /* 4 channels */
        for (y = 0; y < imOut->ysize; y++) {
            UINT8 *rowIn = (UINT8 *)imIn->image[y];
            UINT8 *rowOut = (UINT8 *)imOut->image[y];
            int rowInOffset = 0;
            int rowOutOffset = 0;

