                INT16 ll3 = t[3] + ((t[7] - t[3]) * shift1D >> SHIFT_BITS);

                INT16 lr0 = t[size1D * 4] + ((t[size1D * 4 + 4] - t[size1D * 4]) * shift1D >> SHIFT_BITS);
                INT16 lr1 = t[size1D * 4 + 1] + ((t[size1D * 4 + 5] - t[size1D * 4 + 1]) * shift1D >> SHIFT_BITS);
                INT16 lr2 = t[size1D * 4 + 2] + ((t[size1D * 4 + 6] - t[size1D * 4 + 2]) * shift1D >> SHIFT_BITS);
                INT16 lr3 = t[size1D * 4 + 3] + ((t[size1D * 4 + 7] - t[size1D * 4 + 3]) * shift1D >> SHIFT_BITS);

                INT16 l0 = ll0 + ((lr0 - ll0) * shift2D >> SHIFT_BITS);
                INT16 l1 = ll1 + ((lr1 - ll1) * shift2D >> SHIFT_BITS);
                INT16 l2 = ll2 + ((lr2 - ll2) * shift2D >> SHIFT_BITS);
                INT16 l3 = ll3 + ((lr3 - ll3) * shift2D >> SHIFT_BITS);

                INT16 rl0 = t[size1D_2D * 4] + ((t[size1D_2D * 4 + 4] - t[size1D_2D * 4]) * shift1D >> SHIFT_BITS);
                INT16 rl1 = t[size1D_2D * 4 + 1] + ((t[size1D_2D * 4 + 5] - t[size1D_2D * 4 + 1]) * shift1D >> SHIFT_BITS);
                INT16 rl2 = t[size1D_2D * 4 + 2] + ((t[size1D_2D * 4 + 6] - t[size1D_2D * 4 + 2]) * shift1D >> SHIFT_BITS);
                INT16 rl3 = t[size1D_2D * 4 + 3] + ((t[size1D_2D * 4 + 7] - t[size1D_2D * 4 + 3]) * shift1D >> SHIFT_BITS);

                INT16 rr0 = t[size1D_2D * 4 + size1D * 4] + ((t[size1D_2D * 4 + size1D * 4 + 4] - t[size1D_2D * 4 + size1D * 4]) * shift1D >> SHIFT_BITS);
                INT16 rr1 = t[size1D_2D * 4 + size1D * 4 + 1] + ((t[size1D_2D * 4 + size1D * 4 + 5] - t[size1D_2D * 4 + size1D * 4 + 1]) * shift1D >> SHIFT_BITS);
                INT16 rr2 = t[size1D_2D * 4 + size1D * 4 + 2] + ((t[size1D_2D * 4 + size1D * 4 + 6] - t[size1D_2D * 4 + size1D * 4 + 2]) * shift1D >> SHIFT_BITS);
                INT16 rr3 = t[size1D_2D * 4 + size1D * 4 + 3] + ((t[size1D_2D * 4 + size1D * 4 + 7] - t[size1D_2D * 4 + size1D * 4 + 3]) * shift1D >> SHIFT_BITS);

                INT16 r0 = rl0 + ((rr0 - rl0) * shift2D >> SHIFT_BITS);
                INT16 r1 = rl1 + ((rr1 - rl1) * shift2D >> SHIFT_BITS);
                INT16 r2 = rl2 + ((rr2 - rl2) * shift2D >> SHIFT_BITS);
                INT16 r3 = rl3 + ((rr3 - rl3) * shift2D >> SHIFT_BITS);

                INT16 shift3D_inv = SHIFT_ONE - shift3D;
                INT16 result0 = (l0 * shift3D_inv + r0 * shift3D) >> SHIFT_BITS;
                INT16 result1 = (l1 * shift3D_inv + r1 * shift3D) >> SHIFT_BITS;
                INT16 result2 = (l2 * shift3D_inv + r2 * shift3D) >> SHIFT_BITS;
                INT16 result3 = (l3 * shift3D_inv + r3 * shift3D) >> SHIFT_BITS;

                rowOut[rowOutOffset] = clip8_lookups[(result0 + PRECISION_ROUNDING) >> PRECISION_BITS];
