                rowOut[x * 4] = clip8_lookups[(result0 + PRECISION_ROUNDING) >> PRECISION_BITS];
                rowOut[x * 4 + 1] = clip8_lookups[(result1 + PRECISION_ROUNDING) >> PRECISION_BITS];
