                INT16 ll0 = (t[0] * (SHIFT_ONE - shift1D) + t[4] * shift1D) >> SHIFT_BITS;
                INT16 ll1 = (t[1] * (SHIFT_ONE - shift1D) + t[5] * shift1D) >> SHIFT_BITS;
                INT16 ll2 = (t[2] * (SHIFT_ONE - shift1D) + t[6] * shift1D) >> SHIFT_BITS;
                INT16 ll3 = (t[3] * (SHIFT_ONE - shift1D) + t[7] * shift1D) >> SHIFT_BITS;

                INT16 lr0 = (t[size1D * 4] * (SHIFT_ONE - shift1D) + t[size1D * 4 + 4] * shift1D) >> SHIFT_BITS;
                INT16 lr1 = (t[size1D * 4 + 1] * (SHIFT_ONE - shift1D) + t[size1D * 4 + 5] * shift1D) >> SHIFT_BITS;
                INT16 lr2 = (t[size1D * 4 + 2] * (SHIFT_ONE - shift1D) + t[size1D * 4 + 6] * shift1D) >> SHIFT_BITS;
                INT16 lr3 = (t[size1D * 4 + 3] * (SHIFT_ONE - shift1D) + t[size1D * 4 + 7] * shift1D) >> SHIFT_BITS;

                INT16 l0 = (ll0 * (SHIFT_ONE - shift2D) + lr0 * shift2D) >> SHIFT_BITS;
                INT16 l1 = (ll1 * (SHIFT_ONE - shift2D) + lr1 * shift2D) >> SHIFT_BITS;
                INT16 l2 = (ll2 * (SHIFT_ONE - shift2D) + lr2 * shift2D) >> SHIFT_BITS;
                INT16 l3 = (ll3 * (SHIFT_ONE - shift2D) + lr3 * shift2D) >> SHIFT_BITS;

                INT16 rl0 = (t[size1D_2D * 4] * (SHIFT_ONE - shift1D) + t[size1D_2D * 4 + 4] * shift1D) >> SHIFT_BITS;
                INT16 rl1 = (t[size1D_2D * 4 + 1] * (SHIFT_ONE - shift1D) + t[size1D_2D * 4 + 5] * shift1D) >> SHIFT_BITS;
                INT16 rl2 = (t[size1D_2D * 4 + 2] * (SHIFT_ONE - shift1D) + t[size1D_2D * 4 + 6] * shift1D) >> SHIFT_BITS;
                INT16 rl3 = (t[size1D_2D * 4 + 3] * (SHIFT_ONE - shift1D) + t[size1D_2D * 4 + 7] * shift1D) >> SHIFT_BITS;

                INT16 rr0 = (t[size1D_2D * 4 + size1D * 4] * (SHIFT_ONE - shift1D) + t[size1D_2D * 4 + size1D * 4 + 4] * shift1D) >> SHIFT_BITS;
                INT16 rr1 = (t[size1D_2D * 4 + size1D * 4 + 1] * (SHIFT_ONE - shift1D) + t[size1D_2D * 4 + size1D * 4 + 5] * shift1D) >> SHIFT_BITS;
                INT16 rr2 = (t[size1D_2D * 4 + size1D * 4 + 2] * (SHIFT_ONE - shift1D) + t[size1D_2D * 4 + size1D * 4 + 6] * shift1D) >> SHIFT_BITS;
                INT16 rr3 = (t[size1D_2D * 4 + size1D * 4 + 3] * (SHIFT_ONE - shift1D) + t[size1D_2D * 4 + size1D * 4 + 7] * shift1D) >> SHIFT_BITS;

                INT16 r0 = (rl0 * (SHIFT_ONE - shift2D) + rr0 * shift2D) >> SHIFT_BITS;
                INT16 r1 = (rl1 * (SHIFT_ONE - shift2D) + rr1 * shift2D) >> SHIFT_BITS;
                INT16 r2 = (rl2 * (SHIFT_ONE - shift2D) + rr2 * shift2D) >> SHIFT_BITS;
                INT16 r3 = (rl3 * (SHIFT_ONE - shift2D) + rr3 * shift2D) >> SHIFT_BITS;

                INT16 shift3D_inv = SHIFT_ONE - shift3D;
                INT16 result0 = (l0 * shift3D_inv + r0 * shift3D) >> SHIFT_BITS;
                INT16 result1 = (l1 * shift3D_inv + r1 * shift3D) >> SHIFT_BITS;
                INT16 result2 = (l2 * shift3D_inv + r2 * shift3D) >> SHIFT_BITS;
                INT16 result3 = (l3 * shift3D_inv + r3 * shift3D) >> SHIFT_BITS;

                rowOut[x * 4] = clip8(result0);
                rowOut[x * 4 + 1] = clip8(result1);
                rowOut[x * 4 + 2] = clip8(result2);
                rowOut[x * 4 + 3] = clip8(result3);
            }
        }
    }

    ImagingSectionLeave(&cookie);

    return imOut;
}

/*
 * SSSE3/SSE4.2 optimized version.
 * Uses pshufb to extract RGB channels and computes multiple pixels together.
 */
static Imaging
ImagingColorLUT3D_linear_simd(
    Imaging imOut,
    Imaging imIn,
    int table_channels,
    int size1D,
    int size2D,
    int size3D,
    INT16 *table) {

    UINT32 scale1D = (size1D - 1) / 255.0f * (1 << SCALE_BITS);
    UINT32 scale2D = (size2D - 1) / 255.0f * (1 << SCALE_BITS);
    UINT32 scale3D = (size3D - 1) / 255.0f * (1 << SCALE_BITS);
    int size1D_2D = size1D * size2D;
    int x, y;
    ImagingSectionCookie cookie;

    if (table_channels < 3 || table_channels > 4) {
        PyErr_SetString(PyExc_ValueError, "table_channels could be 3 or 4");
        return NULL;
    }

    if (imIn->type != IMAGING_TYPE_UINT8 || imOut->type != IMAGING_TYPE_UINT8 ||
        imIn->bands < 3 || imOut->bands < table_channels) {
        return (Imaging)ImagingError_ModeError();
    }

    if (imOut->bands > table_channels && imOut->bands > imIn->bands) {
        return (Imaging)ImagingError_ModeError();
    }

    ImagingSectionEnter(&cookie);

    /* Shuffle masks for extracting RGB channels from packed RGBA pixels */
    /* pshufb expects index of each byte position (0-15), high bit clears */
    /* For pixels R0,G0,B0,A0,R1,G1,B1,A1,... */
    /* R channel: bytes 0,4,8,12 -> _mm_set_epi8(12,0, 8,0, 4,0, 0,0, 12,0, 8,0, 4,0, 0,0) */
    /* But pshufb uses low 4 bits only, so we use 0x0C, 0x00, etc. */
    const __m128i mask_r = _mm_set_epi8(
        0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80,  /* padding */
        12, 0, 8, 0, 4, 0, 0, 0);  /* R from 4 pixels */

    if (table_channels == 3) {
        int xsimd = (imOut->xsize / 4) * 4;

        for (y = 0; y < imOut->ysize; y++) {
            UINT8 *rowIn = (UINT8 *)imIn->image[y];
            UINT8 *rowOut = (UINT8 *)imOut->image[y];

            for (x = 0; x < xsimd; x += 4) {
                /* Load 4 pixels (16 bytes) */
                __m128i pixels = _mm_loadu_si128((__m128i *)(rowIn + x * 4));

                /* Extract R channel using SSSE3 pshufb */
                __m128i r_vals = _mm_shuffle_epi8(pixels, mask_r);
                /* Zero-extend to 32-bit */
                __m128i r_vals_lo = _mm_unpacklo_epi8(r_vals, _mm_setzero_si128());
                __m128i r_vals_hi = _mm_unpackhi_epi8(r_vals, _mm_setzero_si128());

                /* Compute scaled indices */
                __m128i scale1D_v = _mm_set1_epi32(scale1D);
                __m128i scale2D_v = _mm_set1_epi32(scale2D);
                __m128i scale3D_v = _mm_set1_epi32(scale3D);

                __m128i r_scaled_lo = _mm_mullo_epi32(r_vals_lo, scale1D_v);
                __m128i r_scaled_hi = _mm_mullo_epi32(r_vals_hi, scale1D_v);

                /* Store and process in scalar */
                int r_idx[4], g_idx[4], b_idx[4];
                int r_shift[4], g_shift[4], b_shift[4];

                _mm_storeu_si128((__m128i *)r_idx, r_scaled_lo);
                _mm_storeu_si128((__m128i *)(r_idx + 2), r_scaled_hi);

                /* Now get G channel - need to shift the mask */
                const __m128i mask_g = _mm_set_epi8(
                    0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80,
                    13, 1, 9, 1, 5, 1, 1, 1);

                __m128i g_vals = _mm_shuffle_epi8(pixels, mask_g);
                __m128i g_vals_lo = _mm_unpacklo_epi8(g_vals, _mm_setzero_si128());
                __m128i g_vals_hi = _mm_unpackhi_epi8(g_vals, _mm_setzero_si128());

                __m128i g_scaled_lo = _mm_mullo_epi32(g_vals_lo, scale2D_v);
                __m128i g_scaled_hi = _mm_mullo_epi32(g_vals_hi, scale2D_v);

                _mm_storeu_si128((__m128i *)g_idx, g_scaled_lo);
                _mm_storeu_si128((__m128i *)(g_idx + 2), g_scaled_hi);

                /* B channel */
                const __m128i mask_b = _mm_set_epi8(
                    0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80,
                    14, 2, 10, 2, 6, 2, 2, 2);

                __m128i b_vals = _mm_shuffle_epi8(pixels, mask_b);
                __m128i b_vals_lo = _mm_unpacklo_epi8(b_vals, _mm_setzero_si128());
                __m128i b_vals_hi = _mm_unpackhi_epi8(b_vals, _mm_setzero_si128());

                __m128i b_scaled_lo = _mm_mullo_epi32(b_vals_lo, scale3D_v);
                __m128i b_scaled_hi = _mm_mullo_epi32(b_vals_hi, scale3D_v);

                _mm_storeu_si128((__m128i *)b_idx, b_scaled_lo);
                _mm_storeu_si128((__m128i *)(b_idx + 2), b_scaled_hi);

                /* Process all 4 pixels */
                for (int i = 0; i < 4; i++) {
                    r_shift[i] = (r_idx[i] & SCALE_MASK) >> (SCALE_BITS - SHIFT_BITS);
                    g_shift[i] = (g_idx[i] & SCALE_MASK) >> (SCALE_BITS - SHIFT_BITS);
                    b_shift[i] = (b_idx[i] & SCALE_MASK) >> (SCALE_BITS - SHIFT_BITS);

                    r_idx[i] >>= SCALE_BITS;
                    g_idx[i] >>= SCALE_BITS;
                    b_idx[i] >>= SCALE_BITS;
                }

                for (int i = 0; i < 4; i++) {
                    INT32 idx = (r_idx[i] + g_idx[i] * size1D + b_idx[i] * size1D_2D) * 3;
                    INT16 shift1D = r_shift[i];
                    INT16 shift2D = g_shift[i];
                    INT16 shift3D = b_shift[i];
                    INT16 *t = &table[idx];

                    INT16 ll0 = (t[0] * (SHIFT_ONE - shift1D) + t[3] * shift1D) >> SHIFT_BITS;
                    INT16 ll1 = (t[1] * (SHIFT_ONE - shift1D) + t[4] * shift1D) >> SHIFT_BITS;
                    INT16 ll2 = (t[2] * (SHIFT_ONE - shift1D) + t[5] * shift1D) >> SHIFT_BITS;

                    INT16 lr0 = (t[size1D * 3] * (SHIFT_ONE - shift1D) + t[size1D * 3 + 3] * shift1D) >> SHIFT_BITS;
                    INT16 lr1 = (t[size1D * 3 + 1] * (SHIFT_ONE - shift1D) + t[size1D * 3 + 4] * shift1D) >> SHIFT_BITS;
                    INT16 lr2 = (t[size1D * 3 + 2] * (SHIFT_ONE - shift1D) + t[size1D * 3 + 5] * shift1D) >> SHIFT_BITS;

                    INT16 l0 = (ll0 * (SHIFT_ONE - shift2D) + lr0 * shift2D) >> SHIFT_BITS;
                    INT16 l1 = (ll1 * (SHIFT_ONE - shift2D) + lr1 * shift2D) >> SHIFT_BITS;
                    INT16 l2 = (ll2 * (SHIFT_ONE - shift2D) + lr2 * shift2D) >> SHIFT_BITS;

                    INT16 rl0 = (t[size1D_2D * 3] * (SHIFT_ONE - shift1D) + t[size1D_2D * 3 + 3] * shift1D) >> SHIFT_BITS;
                    INT16 rl1 = (t[size1D_2D * 3 + 1] * (SHIFT_ONE - shift1D) + t[size1D_2D * 3 + 4] * shift1D) >> SHIFT_BITS;
                    INT16 rl2 = (t[size1D_2D * 3 + 2] * (SHIFT_ONE - shift1D) + t[size1D_2D * 3 + 5] * shift1D) >> SHIFT_BITS;

                    INT16 rr0 = (t[size1D_2D * 3 + size1D * 3] * (SHIFT_ONE - shift1D) + t[size1D_2D * 3 + size1D * 3 + 3] * shift1D) >> SHIFT_BITS;
                    INT16 rr1 = (t[size1D_2D * 3 + size1D * 3 + 1] * (SHIFT_ONE - shift1D) + t[size1D_2D * 3 + size1D * 3 + 4] * shift1D) >> SHIFT_BITS;
                    INT16 rr2 = (t[size1D_2D * 3 + size1D * 3 + 2] * (SHIFT_ONE - shift1D) + t[size1D_2D * 3 + size1D * 3 + 5] * shift1D) >> SHIFT_BITS;

                    INT16 r0 = (rl0 * (SHIFT_ONE - shift2D) + rr0 * shift2D) >> SHIFT_BITS;
                    INT16 r1 = (rl1 * (SHIFT_ONE - shift2D) + rr1 * shift2D) >> SHIFT_BITS;
                    INT16 r2 = (rl2 * (SHIFT_ONE - shift2D) + rr2 * shift2D) >> SHIFT_BITS;

                    INT16 shift3D_inv = SHIFT_ONE - shift3D;
                    INT16 result0 = (l0 * shift3D_inv + r0 * shift3D) >> SHIFT_BITS;
                    INT16 result1 = (l1 * shift3D_inv + r1 * shift3D) >> SHIFT_BITS;
                    INT16 result2 = (l2 * shift3D_inv + r2 * shift3D) >> SHIFT_BITS;

                    rowOut[(x + i) * 4] = clip8(result0);
                    rowOut[(x + i) * 4 + 1] = clip8(result1);
                    rowOut[(x + i) * 4 + 2] = clip8(result2);
                    rowOut[(x + i) * 4 + 3] = rowIn[(x + i) * 4 + 3];
                }
            }

            /* Handle remaining pixels */
            for (; x < imOut->xsize; x++) {
                UINT32 r = rowIn[x * 4];
                UINT32 g = rowIn[x * 4 + 1];
                UINT32 b = rowIn[x * 4 + 2];

                UINT32 index1D = r * scale1D;
                UINT32 index2D = g * scale2D;
                UINT32 index3D = b * scale3D;

                INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);

                INT32 idx = ((index1D >> SCALE_BITS) + (index2D >> SCALE_BITS) * size1D + (index3D >> SCALE_BITS) * size1D_2D) * 3;
                INT16 *t = &table[idx];

                INT16 ll0 = (t[0] * (SHIFT_ONE - shift1D) + t[3] * shift1D) >> SHIFT_BITS;
                INT16 ll1 = (t[1] * (SHIFT_ONE - shift1D) + t[4] * shift1D) >> SHIFT_BITS;
                INT16 ll2 = (t[2] * (SHIFT_ONE - shift1D) + t[5] * shift1D) >> SHIFT_BITS;

                INT16 lr0 = (t[size1D * 3] * (SHIFT_ONE - shift1D) + t[size1D * 3 + 3] * shift1D) >> SHIFT_BITS;
                INT16 lr1 = (t[size1D * 3 + 1] * (SHIFT_ONE - shift1D) + t[size1D * 3 + 4] * shift1D) >> SHIFT_BITS;
                INT16 lr2 = (t[size1D * 3 + 2] * (SHIFT_ONE - shift1D) + t[size1D * 3 + 5] * shift1D) >> SHIFT_BITS;

                INT16 l0 = (ll0 * (SHIFT_ONE - shift2D) + lr0 * shift2D) >> SHIFT_BITS;
                INT16 l1 = (ll1 * (SHIFT_ONE - shift2D) + lr1 * shift2D) >> SHIFT_BITS;
                INT16 l2 = (ll2 * (SHIFT_ONE - shift2D) + lr2 * shift2D) >> SHIFT_BITS;

                INT16 rl0 = (t[size1D_2D * 3] * (SHIFT_ONE - shift1D) + t[size1D_2D * 3 + 3] * shift1D) >> SHIFT_BITS;
                INT16 rl1 = (t[size1D_2D * 3 + 1] * (SHIFT_ONE - shift1D) + t[size1D_2D * 3 + 4] * shift1D) >> SHIFT_BITS;
                INT16 rl2 = (t[size1D_2D * 3 + 2] * (SHIFT_ONE - shift1D) + t[size1D_2D * 3 + 5] * shift1D) >> SHIFT_BITS;

                INT16 rr0 = (t[size1D_2D * 3 + size1D * 3] * (SHIFT_ONE - shift1D) + t[size1D_2D * 3 + size1D * 3 + 3] * shift1D) >> SHIFT_BITS;
                INT16 rr1 = (t[size1D_2D * 3 + size1D * 3 + 1] * (SHIFT_ONE - shift1D) + t[size1D_2D * 3 + size1D * 3 + 4] * shift1D) >> SHIFT_BITS;
                INT16 rr2 = (t[size1D_2D * 3 + size1D * 3 + 2] * (SHIFT_ONE - shift1D) + t[size1D_2D * 3 + size1D * 3 + 5] * shift1D) >> SHIFT_BITS;

                INT16 r0 = (rl0 * (SHIFT_ONE - shift2D) + rr0 * shift2D) >> SHIFT_BITS;
                INT16 r1 = (rl1 * (SHIFT_ONE - shift2D) + rr1 * shift2D) >> SHIFT_BITS;
                INT16 r2 = (rl2 * (SHIFT_ONE - shift2D) + rr2 * shift2D) >> SHIFT_BITS;

                INT16 shift3D_inv = SHIFT_ONE - shift3D;
                INT16 result0 = (l0 * shift3D_inv + r0 * shift3D) >> SHIFT_BITS;
                INT16 result1 = (l1 * shift3D_inv + r1 * shift3D) >> SHIFT_BITS;
                INT16 result2 = (l2 * shift3D_inv + r2 * shift3D) >> SHIFT_BITS;

                rowOut[x * 4] = clip8(result0);
                rowOut[x * 4 + 1] = clip8(result1);
                rowOut[x * 4 + 2] = clip8(result2);
                rowOut[x * 4 + 3] = rowIn[x * 4 + 3];
            }
        }
    } else {
        /* 4 channels - use scalar fallback */
        for (y = 0; y < imOut->ysize; y++) {
            UINT8 *rowIn = (UINT8 *)imIn->image[y];
            UINT8 *rowOut = (UINT8 *)imOut->image[y];

            for (x = 0; x < imOut->xsize; x++) {
                UINT32 r = rowIn[x * 4];
                UINT32 g = rowIn[x * 4 + 1];
                UINT32 b = rowIn[x * 4 + 2];

                UINT32 index1D = r * scale1D;
                UINT32 index2D = g * scale2D;
                UINT32 index3D = b * scale3D;

                INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);

                INT32 idx = ((index1D >> SCALE_BITS) + (index2D >> SCALE_BITS) * size1D + (index3D >> SCALE_BITS) * size1D_2D) * 4;
                INT16 *t = &table[idx];

                INT16 ll0 = (t[0] * (SHIFT_ONE - shift1D) + t[4] * shift1D) >> SHIFT_BITS;
                INT16 ll1 = (t[1] * (SHIFT_ONE - shift1D) + t[5] * shift1D) >> SHIFT_BITS;
                INT16 ll2 = (t[2] * (SHIFT_ONE - shift1D) + t[6] * shift1D) >> SHIFT_BITS;
                INT16 ll3 = (t[3] * (SHIFT_ONE - shift1D) + t[7] * shift1D) >> SHIFT_BITS;

                INT16 lr0 = (t[size1D * 4] * (SHIFT_ONE - shift1D) + t[size1D * 4 + 4] * shift1D) >> SHIFT_BITS;
                INT16 lr1 = (t[size1D * 4 + 1] * (SHIFT_ONE - shift1D) + t[size1D * 4 + 5] * shift1D) >> SHIFT_BITS;
                INT16 lr2 = (t[size1D * 4 + 2] * (SHIFT_ONE - shift1D) + t[size1D * 4 + 6] * shift1D) >> SHIFT_BITS;
                INT16 lr3 = (t[size1D * 4 + 3] * (SHIFT_ONE - shift1D) + t[size1D * 4 + 7] * shift1D) >> SHIFT_BITS;

                INT16 l0 = (ll0 * (SHIFT_ONE - shift2D) + lr0 * shift2D) >> SHIFT_BITS;
                INT16 l1 = (ll1 * (SHIFT_ONE - shift2D) + lr1 * shift2D) >> SHIFT_BITS;
                INT16 l2 = (ll2 * (SHIFT_ONE - shift2D) + lr2 * shift2D) >> SHIFT_BITS;
                INT16 l3 = (ll3 * (SHIFT_ONE - shift2D) + lr3 * shift2D) >> SHIFT_BITS;

                INT16 rl0 = (t[size1D_2D * 4] * (SHIFT_ONE - shift1D) + t[size1D_2D * 4 + 4] * shift1D) >> SHIFT_BITS;
                INT16 rl1 = (t[size1D_2D * 4 + 1] * (SHIFT_ONE - shift1D) + t[size1D_2D * 4 + 5] * shift1D) >> SHIFT_BITS;
                INT16 rl2 = (t[size1D_2D * 4 + 2] * (SHIFT_ONE - shift1D) + t[size1D_2D * 4 + 6] * shift1D) >> SHIFT_BITS;
                INT16 rl3 = (t[size1D_2D * 4 + 3] * (SHIFT_ONE - shift1D) + t[size1D_2D * 4 + 7] * shift1D) >> SHIFT_BITS;

                INT16 rr0 = (t[size1D_2D * 4 + size1D * 4] * (SHIFT_ONE - shift1D) + t[size1D_2D * 4 + size1D * 4 + 4] * shift1D) >> SHIFT_BITS;
                INT16 rr1 = (t[size1D_2D * 4 + size1D * 4 + 1] * (SHIFT_ONE - shift1D) + t[size1D_2D * 4 + size1D * 4 + 5] * shift1D) >> SHIFT_BITS;
                INT16 rr2 = (t[size1D_2D * 4 + size1D * 4 + 2] * (SHIFT_ONE - shift1D) + t[size1D_2D * 4 + size1D * 4 + 6] * shift1D) >> SHIFT_BITS;
                INT16 rr3 = (t[size1D_2D * 4 + size1D * 4 + 3] * (SHIFT_ONE - shift1D) + t[size1D_2D * 4 + size1D * 4 + 7] * shift1D) >> SHIFT_BITS;

                INT16 r0 = (rl0 * (SHIFT_ONE - shift2D) + rr0 * shift2D) >> SHIFT_BITS;
                INT16 r1 = (rl1 * (SHIFT_ONE - shift2D) + rr1 * shift2D) >> SHIFT_BITS;
                INT16 r2 = (rl2 * (SHIFT_ONE - shift2D) + rr2 * shift2D) >> SHIFT_BITS;
                INT16 r3 = (rl3 * (SHIFT_ONE - shift2D) + rr3 * shift2D) >> SHIFT_BITS;

                INT16 shift3D_inv = SHIFT_ONE - shift3D;
                INT16 result0 = (l0 * shift3D_inv + r0 * shift3D) >> SHIFT_BITS;
                INT16 result1 = (l1 * shift3D_inv + r1 * shift3D) >> SHIFT_BITS;
                INT16 result2 = (l2 * shift3D_inv + r2 * shift3D) >> SHIFT_BITS;
                INT16 result3 = (l3 * shift3D_inv + r3 * shift3D) >> SHIFT_BITS;

                rowOut[x * 4] = clip8(result0);
                rowOut[x * 4 + 1] = clip8(result1);
                rowOut[x * 4 + 2] = clip8(result2);
                rowOut[x * 4 + 3] = clip8(result3);
            }
        }
    }

    ImagingSectionLeave(&cookie);

    return imOut;
}

/* Choose implementation based on available SIMD instructions */
Imaging
ImagingColorLUT3D_linear(
    Imaging imOut,
    Imaging imIn,
    int table_channels,
    int size1D,
    int size2D,
    int size3D,
    INT16 *table) {
#if defined(__SSE4_2__) || defined(__SSSE3__)
    return ImagingColorLUT3D_linear_simd(imOut, imIn, table_channels, size1D, size2D, size3D, table);
#else
    return ImagingColorLUT3D_linear_c(imOut, imIn, table_channels, size1D, size2D, size3D, table);
#endif
}

